-- WorldMapPins: world bosses, custom services, hub portals and transport stations.
--
-- Only content this project adds (Warpweaver, Call Board) plus the approved exceptions: the
-- seven outdoor world bosses, the hub portal network and the player ship/zeppelin stations.
-- Stock NPC categories (flight masters, innkeepers, battlemasters, meeting stones, city
-- leaders) are deliberately absent; addons such as Questie cover those.
--
-- Pin rows live in src/WorldMapPins/data/*.lua and are generated by generate.py from tracked
-- SQL plus WorldMapArea.dbc, WorldMapTransforms.dbc and DungeonMap.dbc. Do not edit by hand.
--
-- mx/my are zone-map fractions and cx/cy continent fractions. 3.3.5 zone maps rotate the axes:
--   mx = (yMax - worldY) / (yMax - yMin), my = (xMax - worldX) / (xMax - xMin)
-- Silvermoon and the Exodar stand on map 530 but display on map 0 and 1, so their continent
-- fraction applies the additive WorldMapTransforms offset before projecting.

local ADDON, ns = ...

local Frame = CreateFrame("Frame")
Frame.pins = {}

local ICONS = {
    boss = "Interface\\TargetingFrame\\UI-RaidTargetingIcon_8",
    warpweaver = "Interface\\Icons\\INV_NetherPortal",
    callboard = "Interface\\GossipFrame\\AvailableQuestIcon",
    -- Portal pins carry their own per-room icon; this is only the fallback.
    portal = "Interface\\Icons\\Spell_Arcane_PortalShattrath",
    ship = "Interface\\Icons\\INV_ShipMount",
    zeppelin = "Interface\\Icons\\INV_ZeppelinMount",
}

-- Filled by data/*.lua, which the TOC loads before this file. The kinds are listed by name and
-- a missing table is skipped, because ipairs over a table of lists stops at the first nil: one
-- data file failing to load would silently drop every kind after it.
ns.Pins = {}
for _, key in ipairs({ "PinBosses", "PinServices", "PinPortals", "PinTransports" }) do
    for _, pin in ipairs(ns[key] or {}) do
        if not pin.icon and not ICONS[pin.kind] then
            error("WorldMapPins: no icon for pin kind " .. tostring(pin.kind))
        end
        ns.Pins[#ns.Pins + 1] = pin
    end
end
if #ns.Pins == 0 then
    error("WorldMapPins: no pin data loaded; src/WorldMapPins/data/*.lua is missing")
end

local ZONE_BY_NAME = {}
local function Normalize(name)
    name = string.lower(name or "")
    name = name:gsub("^the%s+", "")
    name = name:gsub("%s+city$", "")
    name = name:gsub("'", "")
    return name
end

local function IndexZones()
    for zone, name in pairs(ns.Zones or {}) do
        ZONE_BY_NAME[Normalize(name)] = zone
    end
end
IndexZones()

-- The map tooltip, not GameTooltip. WorldMapTooltip is a GameTooltip at TOOLTIP strata
-- parented to WorldMapFrame; the client uses it for every other map hover (units, quest
-- POIs, the buttons), so it is the one that renders above the map texture.
local function Tooltip()
    return WorldMapTooltip or GameTooltip
end

-- Pins are children of WorldMapFrame at its frame level + 7, with the frame's strata copied.
-- That is the arrangement Questie uses in this client (HandyNotes uses +6) and it is the one
-- proven to receive hover and click. The previous build was a child of WorldMapButton at
-- WORLDMAP_POI_FRAMELEVEL + 50: it drew, but no mouse event ever reached it.
--
-- Level 94 is below the quest POI frame (100) on purpose. `WorldMapPOIFrame` itself is not
-- mouse-enabled, so it does not block the pin. Only its child quest icons do, and a pin that
-- lands exactly on one loses the mouse there. Raising the level would break the arrangement
-- that is known to work in this client.
local function PlaceLevel(button)
    if WorldMapFrame then
        button:SetFrameStrata(WorldMapFrame:GetFrameStrata())
        button:SetFrameLevel(WorldMapFrame:GetFrameLevel() + 7)
    end
end

local function CreatePin(pin)
    local button = CreateFrame("Button", nil, WorldMapFrame)
    button:SetWidth(24)
    button:SetHeight(24)
    PlaceLevel(button)
    button:EnableMouse(true)
    button:RegisterForClicks("LeftButtonUp")

    local icon = button:CreateTexture(nil, "ARTWORK")
    icon:SetWidth(14)
    icon:SetHeight(14)
    icon:SetPoint("CENTER")
    icon:SetTexture(pin.icon or ICONS[pin.kind])
    button.icon = icon
    button.pin = pin

    button:SetScript("OnEnter", function(self)
        local tip = Tooltip()
        if not tip then
            return
        end
        -- Stop WorldMapBlobFrame_OnUpdate from swapping the tooltip back to the quest blob
        -- under the cursor while the pin is hovered.
        if WorldMapPOIFrame then
            WorldMapPOIFrame.allowBlobTooltip = false
        end
        tip:SetOwner(self, "ANCHOR_RIGHT")
        -- The city is in the title, not only in a lower line. On a continent map a city's
        -- Warpweaver and Call Board sit 1-7 pixels apart, so only the top pin of the pair can be
        -- hovered; the title has to say which service and which city that top pin is. Portal and
        -- transport pins carry an explicit title and subtitle instead.
        if self.pin.title then
            tip:SetText(self.pin.title)
            if self.pin.subtitle and self.pin.subtitle ~= "" then
                tip:AddLine(self.pin.subtitle, 0.8, 0.8, 0.8)
            end
        elseif self.pin.kind == "boss" then
            tip:SetText(self.pin.label)
            tip:AddLine(self.pin.note .. " - " .. self.pin.place, 0.8, 0.8, 0.8)
        else
            tip:SetText(self.pin.place)
            tip:AddLine(self.pin.label .. " - " .. self.pin.note, 0.8, 0.8, 0.8)
        end
        -- Portals and transports list every destination, one per line.
        for _, line in ipairs(self.pin.lines or {}) do
            tip:AddLine(line, 0.85, 0.85, 0.85)
        end
        tip:Show()
    end)
    button:SetScript("OnLeave", function()
        local tip = Tooltip()
        if tip then
            tip:Hide()
        end
        if WorldMapPOIFrame then
            WorldMapPOIFrame.allowBlobTooltip = true
        end
    end)
    button:SetScript("OnClick", function(self, mouseButton)
        local tip = Tooltip()
        if tip then
            tip:Hide()
        end
        -- Keep the stock map click (ping) working through the pin.
        if WorldMapButton_OnClick then
            WorldMapButton_OnClick(WorldMapButton, mouseButton)
        end
    end)
    return button
end

local function HideAll()
    for _, button in ipairs(Frame.pins) do
        button:Hide()
    end
    local tip = Tooltip()
    if tip then
        tip:Hide()
    end
    -- A hide while a pin is hovered must not leave the quest blob tooltip switched off.
    if WorldMapPOIFrame then
        WorldMapPOIFrame.allowBlobTooltip = true
    end
end

-- A pin draws on its own zone map and on the zone maps that contain it. The Thunder Bluff pins
-- store zone 1638, so matching the id alone would leave the Mulgore map empty; the generator
-- attaches the curated parent zone to each pin instead of guessing geometrically, because the
-- city bounds overlap three outdoor zones apiece.
local function OnZoneMap(pin, zone)
    if pin.zone == zone then
        return true
    end
    for _, parent in ipairs(pin.zones or {}) do
        if parent == zone then
            return true
        end
    end
    return false
end

local function DisplayedZone(continent, index)
    if not continent or continent < 1 or continent > 4 or not index or index == 0
        or not GetMapZones then
        return nil
    end
    local name = select(index, GetMapZones(continent))
    if not name then
        return nil
    end
    return ZONE_BY_NAME[Normalize(name)]
end

local function Refresh()
    if not WorldMapButton or not WorldMapFrame then
        return
    end
    if not WorldMapFrame:IsShown() then
        HideAll()
        return
    end
    local continent = GetCurrentMapContinent and GetCurrentMapContinent()
    local index = GetCurrentMapZone and GetCurrentMapZone()
    local zone = DisplayedZone(continent, index)
    local onContinent = index == 0 and continent ~= nil and continent >= 1 and continent <= 4
    -- The pins are children of WorldMapFrame, which is not scaled. WorldMapButton is scaled
    -- to the current map size, so the offsets must use its displayed size, not its raw size.
    local scale = WorldMapButton:GetScale() or 1
    local width = WorldMapButton:GetWidth() * scale
    local height = WorldMapButton:GetHeight() * scale

    for i, pin in ipairs(ns.Pins) do
        local button = Frame.pins[i]
        if not button then
            button = CreatePin(pin)
            Frame.pins[i] = button
        end
        local x, y
        if zone and OnZoneMap(pin, zone) then
            x, y = pin.mx, pin.my
        elseif onContinent and pin.cont == continent then
            x, y = pin.cx, pin.cy
        end
        if x then
            PlaceLevel(button)
            button:ClearAllPoints()
            button:SetPoint("CENTER", WorldMapButton, "TOPLEFT", x * width, -y * height)
            button:Show()
        else
            button:Hide()
        end
    end
end

local function Hook(name, handler)
    if type(_G[name]) == "function" then
        hooksecurefunc(name, handler)
    end
end

Hook("WorldMapFrame_Update", Refresh)
Hook("WorldMapFrame_OnShow", Refresh)
Hook("WorldMapFrame_OnHide", HideAll)

-- `/wmp` prints the frame under the cursor and the pin count. When a hover does not open the
-- tooltip this says whether a pin, the client quest POI layer, or something else owns the
-- mouse, without a debugger.
local function Diagnose()
    local out = "WorldMapPins: " .. #ns.Pins .. " pins"
    if not WorldMapFrame or not WorldMapFrame:IsShown() then
        print(out .. ", map closed")
        return
    end
    local frame = GetMouseFocus and GetMouseFocus()
    local name = frame and (frame:GetName() or frame.pin and "pin: " .. frame.pin.label)
    print(out .. ", map open, zone index " .. tostring(GetCurrentMapZone and GetCurrentMapZone())
        .. ", mouse over " .. tostring(name or "nothing"))
end

SLASH_WORLDMAPPINS1 = "/wmp"
SLASH_WORLDMAPPINS2 = "/worldmappins"
SlashCmdList["WORLDMAPPINS"] = Diagnose

if Frame.RegisterEvent then
    Frame:RegisterEvent("PLAYER_LOGIN")
    Frame:SetScript("OnEvent", function(self)
        self:UnregisterEvent("PLAYER_LOGIN")
        if DEFAULT_CHAT_FRAME then
            DEFAULT_CHAT_FRAME:AddMessage(
                "|cff33ff99WorldMapPins|r loaded from patch-Z.MPQ (" .. #ns.Pins .. " pins)."
            )
        end
    end)
end

ns.Refresh = Refresh
ns.DisplayedZone = DisplayedZone
ns.ICONS = ICONS
ns.IndexZones = IndexZones

-- data/zones.lua runs before this file, but a re-index is cheap and makes a late load safe.
if ns.Zones then
    IndexZones()
end
